/* From Uiverse.io by StealthWorm - Tags: loader, interstellar, tars */
.__UIV_SCOPE__ .loader {
  margin: 0 auto;
  display: flex;
  width: 12rem;
  height: 12rem;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  overflow: hidden;
  position: relative;
  border-radius: 50%;
  border: 0.4rem solid #52c5ff;
}

.__UIV_SCOPE__ .container[class*="1"] {
  animation-delay: 1s;
}

.__UIV_SCOPE__ .container[class*="2"] {
  animation-delay: 1.3s;
}

.__UIV_SCOPE__ .container[class*="3"] {
  animation-delay: 1.6s;
}

.__UIV_SCOPE__ .container[class*="4"] {
  animation-delay: 1.9s;
}

.__UIV_SCOPE__ .tars {
  z-index: 0;
  position: absolute;
  height: 100px;
  width: 130px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  transform-style: preserve-3d;
  animation: rotateX3D 6s ease-in-out infinite;
  animation-delay: 1s;
}

.__UIV_SCOPE__ .container {
  position: relative;
  display: flex;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  animation: rotateY3D 3s ease-in infinite both;
}

.__UIV_SCOPE__ .shape {
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  position: relative;
  z-index: -1;
}

.__UIV_SCOPE__ .shape div {
  display: block;
  position: absolute;
  text-align: center;
}

.__UIV_SCOPE__ .container:nth-child(2) .f::after,
.__UIV_SCOPE__ .container:nth-child(3) .f::after {
  position: absolute;
  content: '';
  width: 100%;
  z-index: -1;
  height: 20px;
  background-image: radial-gradient(#54ff6e 2px, transparent 1%);
  background-size: 20px 5px;
  left: 0;
  top: 20%;
  border: 0;
  animation: animMove 2s linear infinite alternate-reverse;
  overflow: hidden;
}

.__UIV_SCOPE__ .container:nth-child(2) .f::before,
.__UIV_SCOPE__ .container:nth-child(3) .f::before {
  position: absolute;
  content: '';
  width: 85%;
  z-index: -1;
  height: 20px;
  left: 0;
  top: 20%;
  border: 0;
  background: #181818;
  border: 2px solid #52c5ff;
  overflow: hidden;
}

.__UIV_SCOPE__ .container:nth-child(1),
.__UIV_SCOPE__ .container:nth-child(4) {
  .__UIV_SCOPE__ & .f: :before,
  .__UIV_SCOPE__ & .r::before,
  .__UIV_SCOPE__ & .l::before {
    position: absolute;
  content: '';
  width: 95%;
  height: 5px;
  left: 0;
  top: 25%;
  border: 1px solid #52c5ff;
  overflow: hidden;
}
}

.__UIV_SCOPE__ .container:nth-child(1) .b::before,
.__UIV_SCOPE__ .container:nth-child(4) .b::before {
  position: absolute;
  content: '';
  width: 95%;
  z-index: -1;
  height: 5px;
  left: 0;
  top: 69%;
  border: 0;
  border: 1px solid #52c5ff;
  overflow: hidden;
}

.__UIV_SCOPE__ .f {
  transform: rotateY(0deg) translateZ(15px);
  border-radius: 2px;
  overflow: hidden;
  transform-style: preserve-3d;
}

.__UIV_SCOPE__ .b {
  transform: rotateX(180deg) translateZ(15px);
  border-radius: 2px;
}

.__UIV_SCOPE__ .f,.__UIV_SCOPE__ .b {
  width: 30px;
  height: 100px;
  background: #212121;
  box-shadow: inset 0 0 0 2px #52c5ff;
  border: 2px solid #52c5ff;
}

.__UIV_SCOPE__ .l {
  transform: rotateY(-90deg) translateZ(0px);
  border-radius: 2px;
}

.__UIV_SCOPE__ .r {
  transform: rotateY(90deg) translateZ(-30px);
  border-radius: 2px;
}

.__UIV_SCOPE__ .l,.__UIV_SCOPE__ .r {
  width: 30px;
  height: 100px;
  left: 15px;
  position: relative;
  z-index: -1;
  background: #212121;
  box-shadow: inset 0 0 0 2px #52c5ff;
  border: 2px solid #52c5ff;
}

.__UIV_SCOPE__ .t {
  transform: rotateX(90deg) translateZ(40px);
  border-radius: 2px;
}

.__UIV_SCOPE__ .bot {
  transform: rotateX(-90deg) translateZ(60px);
  border-radius: 2px;
}

.__UIV_SCOPE__ .t,.__UIV_SCOPE__ .bot {
  width: 30px;
  height: 30px;
  top: 25px;
  position: relative;
  z-index: -1;
  background: #212121;
  box-shadow: inset 0 0 0 2px #52c5ff;
  border: 2px solid #52c5ff;
}

@keyframes rotateY3D {
  0% {
    transform: translateZ(0px) rotateX(0);
  }

  50% {
    transform: translateZ(0px) rotateX(-360deg);
  }

  100% {
    transform: translateZ(0px) rotateX(-360deg);
  }
}

@keyframes rotateX3D {
  0% {
    transform: translateX(0px) rotateY(0);
  }

  50% {
    transform: translateX(0px) rotateY(180deg);
  }

  100% {
    transform: translateX(0px) rotateY(360deg);
  }
}

@keyframes animMove {
  0% {
    transform: translateX(20px);
  }

  100% {
    transform: translateX(-10px);
  }
}
